import{_ as l,a0 as t,w as o,s as d,I as n,x as a,a1 as i,A as p,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"使用 cowsay 命令的 3 種有趣方式 | LCTT x X-CMD","titleTemplate":false,"description":"使用 cowsay 命令的 3 種有趣方式 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 cowsay 命令的 3 種有趣方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 cowsay 命令的 3 種有趣方式 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211117 3 interesting ways to use the Linux cowsay command","title":"使用 cowsay 命令的 3 種有趣方式","tag":"202111","desc":""},"relativePath":"202111/20211117 3 interesting ways to use the Linux cowsay command.md","filePath":"[post].md"}'),r={name:"202111/20211117 3 interesting ways to use the Linux cowsay command.md"};function h(g,s,u,k,b,y){const e=t("Link");return o(),d("div",null,[s[22]||(s[22]=n("h1",{id:"使用-cowsay-命令的-3-種有趣方式",tabindex:"-1"},[a("使用 cowsay 命令的 3 種有趣方式 "),n("a",{class:"header-anchor",href:"#使用-cowsay-命令的-3-種有趣方式","aria-label":"Permalink to “使用 cowsay 命令的 3 種有趣方式”"},"​")],-1)),s[23]||(s[23]=n("blockquote",null,[n("p",null,"想試一個只是好玩的應用嗎？試試 cowsay。")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/25/232451f6v8fnne2np8e22e.jpg",alt:""})],-1)),n("p",null,[s[2]||(s[2]=a("大多數時候，終端是一個生產力的動力源。但是，終端的作用不止是命令和配置。在所有傑出的開源軟件中，有些是 ",-1)),i(e,{href:"https://opensource.com/life/16/6/fun-and-semi-useless-toys-linux"},{default:p(()=>[...s[0]||(s[0]=[a("為了好玩而寫的",-1)])]),_:1}),s[3]||(s[3]=a("。我以前介紹過一些 ",-1)),i(e,{href:"https://opensource.com/article/21/11/fun-linux-commands"},{default:p(()=>[...s[1]||(s[1]=[a("有趣的命令",-1)])]),_:1}),s[4]||(s[4]=a("，但這篇文章只講一個：古老的 ",-1)),s[5]||(s[5]=n("code",null,"cowsay",-1)),s[6]||(s[6]=a(" 命令。",-1))]),s[25]||(s[25]=c(`<p><code>cowsay</code> 是一隻可配置的會説話（或思考）的牛。它接受一個文本字符串，並輸出一個牛説話的圖形。下面是一頭牛在説它喜歡 Linux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; I love Linux &gt;</span></span>
<span class="line"><span>--------------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (oo)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>               ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><p>要得到這個結果，我只需輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay &quot;I love Linux&quot;</span></span></code></pre></div><h3 id="在-linux-上安裝-cowsay" tabindex="-1">在 Linux 上安裝 cowsay <a class="header-anchor" href="#在-linux-上安裝-cowsay" aria-label="Permalink to “在 Linux 上安裝 cowsay”">​</a></h3><p>你可以用你的包管理器安裝 <code>cowsay</code>。在 Debian、Mint、Elementary 和類似的發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cowsay</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cowsay-beefymiracle</span></span></code></pre></div><h3 id="cowsay-命令選項" tabindex="-1">Cowsay 命令選項 <a class="header-anchor" href="#cowsay-命令選項" aria-label="Permalink to “Cowsay 命令選項”">​</a></h3><p><code>cowsay</code> 是一個簡單又有點傻的應用。除了為你的終端機提供一些不同樣式外，它並沒有什麼實際用途。例如，與其讓一頭普通的牛説一個有趣短語，你可以讓一頭長着古怪眼睛的牛説一個有趣的短語。輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay -e @@ Hello</span></span></code></pre></div><p>你會看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; Hello &gt;</span></span>
<span class="line"><span> -------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (@@)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>               ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><p>或者你可以讓它伸出舌頭。輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay -T U Hello</span></span></code></pre></div><p>你會看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; Hello &gt;</span></span>
<span class="line"><span>-------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (oo)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>            U ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><p>更好的是，你可以將 <code>fortune</code> 命令與 <code>cowsay</code> 結合起來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fortune | cowsay</span></span></code></pre></div><p>現在你有了一頭特別睿智的牛：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> _______________________________________</span></span>
<span class="line"><span>/ we:                                   \\</span></span>
<span class="line"><span>|                                       |</span></span>
<span class="line"><span>| The single most important word in the |</span></span>
<span class="line"><span>\\ world.                                /</span></span>
<span class="line"><span> ---------------------------------------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (oo)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>               ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><h3 id="結實的奇蹟" tabindex="-1">“結實的奇蹟” <a class="header-anchor" href="#結實的奇蹟" aria-label="Permalink to ““結實的奇蹟””">​</a></h3><p>在 Fedora 上，有一個額外的 <code>cowsay</code> 選項，也是一個非官方的項目吉祥物。多年來，Fedora 安裝程序一直在展示宣傳開源貢獻的幻燈片。因為它們是根據汽車電影院的插曲設計的，所以幻燈片中常見的卡通人物是擬人化的熱狗。</p><p>為了與這個主題保持一致，你可以用 Fedora 版本的 <code>cowsay</code> 調用一個所謂的“<ruby>結實的奇蹟<rt>beefy miracle</rt></ruby>”。（LCTT 譯註：Fedora 17 的開發代號。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay -f beefymiracle Hello Fedora</span></span></code></pre></div><p>你會得到一個非常傻的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; Hello Fedora &gt;</span></span>
<span class="line"><span> --------------      .---. __</span></span>
<span class="line"><span>          ,    \\    /     \\   \\    ||||</span></span>
<span class="line"><span>         \\\\\\\\      |O___O |    | \\\\||||</span></span>
<span class="line"><span>         \\   //    | \\_/  |    |  \\   /</span></span>
<span class="line"><span>          &#39;--/----/|     /     |   |-&#39;</span></span>
<span class="line"><span>                 //</span><span> //  /     -----&#39;</span></span>
<span class="line"><span>                //  \\\\ /      /</span></span>
<span class="line"><span>               //</span><span>  // /      /</span></span>
<span class="line"><span>              //  \\\\ /      /</span></span>
<span class="line"><span>             //</span><span>  // /      /</span></span>
<span class="line"><span>            /|   &#39; /      /</span></span>
<span class="line"><span>            //\\___/      /</span></span>
<span class="line"><span>           //   ||\\     /</span></span>
<span class="line"><span>           \\\\_  || &#39;---&#39;</span></span>
<span class="line"><span>           /&#39; /  \\\\_.-</span></span>
<span class="line"><span>          /  /    --| |</span></span>
<span class="line"><span>          &#39;-&#39;      |  |</span></span>
<span class="line"><span>                    &#39;-&#39;</span></span></code></pre></div><h3 id="圖形化的-cowsay" tabindex="-1">圖形化的 cowsay <a class="header-anchor" href="#圖形化的-cowsay" aria-label="Permalink to “圖形化的 cowsay”">​</a></h3><p>如果你發現自己需要用圖形化的牛來傳遞信息，可以使用 <code>xcowsay</code> 命令。這是一個類似於 <code>cowsay</code> 的圖形程序，它接受一個由用户輸入的文本字符串，或從另一個應用（如 Fortune）輸送過來的文本字符串。</p><p><img src="https://opensource.com/sites/default/files/uploads/graphical_cowsay.png" alt="A cartoon cow has a speech bubble that reads &quot;I love Linux&quot;" title="graphical cowsay"></p><h3 id="有趣的-linux-命令" tabindex="-1">有趣的 Linux 命令 <a class="header-anchor" href="#有趣的-linux-命令" aria-label="Permalink to “有趣的 Linux 命令”">​</a></h3><p>雖然 <code>cowsay</code> 不是一個有用的命令，但它是一個有趣的命令，相當於你終端的桌面小工具。它很適合用來分散注意力和進行有趣的管道命令實驗（嘗試將 <code>ifconfig</code> 管道到 <code>cowsay</code>，或 <code>lsblk</code> 或 <code>mount</code>，或任何東西！）。如果你想讓你的終端更有趣，試試 <code>cowsay</code>。</p><hr>`,34)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/11/linux-cowsay-command"},{default:p(()=>[...s[7]||(s[7]=[a("https://opensource.com/article/21/11/linux-cowsay-command",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/don-watkins"},{default:p(()=>[...s[9]||(s[9]=[a("Don Watkins",-1)])]),_:1}),s[14]||(s[14]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}